<?php

namespace App\Http\Controllers;

use Illuminate\Http\Response;
use Illuminate\Support\Facades\Storage;

class ThemeController extends Controller
{
    public function __invoke(): Response
    {
        $defaults = ['primary_color' => '#2d8c7e', 'secondary_color' => '#236e63'];
        $disk = Storage::disk('local');
        $saved = $disk->exists('admin-settings.json') ? json_decode($disk->get('admin-settings.json'), true) : [];
        $settings = array_merge($defaults, is_array($saved) ? $saved : []);
        $primary = $settings['primary_color'];
        $secondary = $settings['secondary_color'];

        $css = ':root{--biza-green:'.$primary.';--biza-green-dark:'.$secondary.';--biza-green-light:#5ab5a8;--biza-yellow:#f5c518;--biza-yellow-dark:#d4a810;--biza-dark:#0f1923;--biza-surface:#f8f9fb;--brand:'.$primary.';--brand-dark:'.$secondary.';--ink:#17221d;--muted:#718080;--surface:#f4f8f7;--line:#dce9e7}';
        $css .= '*{margin:0;padding:0;box-sizing:border-box}html{scroll-behavior:smooth}body{font-family:var(--font-tajawal),var(--font-inter),system-ui,-apple-system,Arial,sans-serif;color:#1a2332;background:#fff;-webkit-font-smoothing:antialiased}[dir=rtl] body{font-family:var(--font-tajawal),system-ui,-apple-system,Arial,sans-serif}[dir=ltr] body{font-family:var(--font-inter),system-ui,-apple-system,Arial,sans-serif}::-webkit-scrollbar{width:6px}::-webkit-scrollbar-track{background:#f0f4f8}::-webkit-scrollbar-thumb{background:var(--biza-green);border-radius:10px}::-webkit-scrollbar-thumb:hover{background:var(--biza-green-dark)}.marquee-container{overflow:hidden;white-space:nowrap}.marquee-content{display:inline-flex;animation:marquee 30s linear infinite}.marquee-content:hover{animation-play-state:paused}.floating,.floating-delayed{animation:float 6s ease-in-out infinite}.floating-delayed{animation-delay:2s}.glow-green{box-shadow:0 0 60px rgba(45,140,126,.35)}.glow-yellow{box-shadow:0 0 60px rgba(245,197,24,.35)}.pattern-dots{background-image:radial-gradient(circle,rgba(45,140,126,.08) 1px,transparent 0);background-size:24px 24px}.pattern-grid{background-image:linear-gradient(hsla(0,0%,100%,.04) 1px,transparent 0),linear-gradient(90deg,hsla(0,0%,100%,.04) 1px,transparent 0);background-size:60px 60px}.hero-gradient{background:linear-gradient(135deg,var(--biza-green-dark),var(--biza-green) 55%,var(--biza-green-dark))}.partners-marquee-container{overflow:hidden;position:relative}.partners-marquee-track{display:flex;width:max-content;animation:partnersScroll 35s linear infinite}.partners-marquee-track-reverse{display:flex;width:max-content;animation:partnersScrollReverse 40s linear infinite}.partners-logo-card{width:140px;height:80px;margin:0 20px;flex-shrink:0;position:relative;filter:grayscale(40%) opacity(.75);transition:filter .3s ease}.partners-logo-card:hover{filter:grayscale(0) opacity(1)}@keyframes partnersScroll{0%{transform:translateX(0)}to{transform:translateX(-50%)}}@keyframes partnersScrollReverse{0%{transform:translateX(-50%)}to{transform:translateX(0)}}.card-shine{position:relative;overflow:hidden}.service-number{font-size:4rem;font-weight:900;color:rgba(45,140,126,.07);line-height:1;font-variant-numeric:tabular-nums;position:absolute;top:1rem;inset-inline-end:1.5rem;transition:color .3s}.group:hover .service-number{color:rgba(45,140,126,.13)}[dir=rtl] .marquee-content{animation-direction:reverse}.section-tag{display:inline-flex;align-items:center;gap:6px;padding:6px 16px;background:rgba(45,140,126,.1);color:var(--biza-green);border-radius:999px;font-size:.8125rem;font-weight:600;border:1px solid rgba(45,140,126,.2);margin-bottom:1rem;letter-spacing:.03em}.stat-divider{width:1px;height:40px;background:hsla(0,0%,100%,.2)}';
        $css .= '.btn-primary{border-radius:.75rem;background-color:var(--biza-green);padding:.875rem 2rem;font-weight:600;color:#fff;transition:all .3s cubic-bezier(.4,0,.2,1)}.btn-primary:hover{transform:translateY(-2px);background-color:var(--biza-green-dark);box-shadow:0 20px 25px -5px rgba(0,0,0,.1),0 8px 10px -6px rgba(0,0,0,.1)}.btn-secondary{border-radius:.75rem;background-color:#facc15;padding:.875rem 2rem;font-weight:600;color:#111827;transition:all .3s cubic-bezier(.4,0,.2,1)}.btn-secondary:hover{transform:translateY(-2px);background-color:#eab308;box-shadow:0 20px 25px -5px rgba(0,0,0,.1),0 8px 10px -6px rgba(0,0,0,.1)}.btn-ghost{border-radius:.75rem;border:1px solid hsla(0,0%,100%,.2);padding:.75rem 1.5rem;font-weight:500;color:hsla(0,0%,100%,.9);transition:all .3s cubic-bezier(.4,0,.2,1)}.btn-ghost:hover{border-color:hsla(0,0%,100%,.4);background-color:hsla(0,0%,100%,.1);color:#fff}.section-padding{padding:5rem 1rem}@media (min-width:768px){.section-padding{padding:7rem 2rem}}@media (min-width:1024px){.section-padding{padding-left:4rem;padding-right:4rem}}.heading-1{font-size:2.25rem;line-height:1.1;font-weight:700;letter-spacing:-.025em}@media (min-width:768px){.heading-1{font-size:3rem;line-height:1}}@media (min-width:1024px){.heading-1{font-size:3.75rem;line-height:1}}@media (min-width:1280px){.heading-1{font-size:4.5rem;line-height:1}}.heading-2{font-size:1.875rem;line-height:1.25;font-weight:700;letter-spacing:-.025em}@media (min-width:768px){.heading-2{font-size:2.25rem;line-height:2.5rem}}@media (min-width:1024px){.heading-2{font-size:3rem;line-height:1}}.heading-3{font-size:1.25rem;line-height:1.75rem;font-weight:700;letter-spacing:-.025em}@media (min-width:768px){.heading-3{font-size:1.5rem;line-height:2rem}}.glass-effect{border:1px solid hsla(0,0%,100%,.3);background-color:hsla(0,0%,100%,.8);box-shadow:0 25px 50px -12px rgba(0,0,0,.25);backdrop-filter:blur(24px)}.max-w-7xl{max-width:80rem;margin-left:auto;margin-right:auto}.max-w-4xl{max-width:56rem;margin-left:auto;margin-right:auto}';

        $css .= $this->adminCss();

        return response($css, 200, ['Content-Type' => 'text/css', 'Cache-Control' => 'no-store']);
    }

    private function adminCss(): string
    {
        return '.site-header{display:flex;justify-content:space-between;align-items:center;gap:2rem;padding:1.25rem 6vw;background:#fff}.site-brand,.site-header__brand{display:flex;align-items:center;gap:12px;font-weight:700;font-size:1.4rem}.site-brand img,.site-header__brand img{display:block;object-fit:contain;width:56px;height:56px}.site-shell{min-height:100vh}.homepage__hero{display:grid;grid-template-columns:1.2fr .8fr;align-items:center;gap:3rem;padding:7rem 10vw;background:linear-gradient(135deg,#eef4e8,#fff)}.homepage__hero-content{max-width:680px}.homepage__eyebrow{color:var(--brand);font-weight:700;letter-spacing:.08em;text-transform:uppercase}.homepage__hero h1{margin:.5rem 0 1rem;font-size:clamp(2.5rem,7vw,5.5rem);line-height:.98;color:var(--ink)}.homepage__intro{color:#53605a;font-size:1.15rem;line-height:1.7}.homepage__button{display:inline-block;margin-top:1rem;padding:.85rem 1.6rem;border-radius:999px;background:#fff;color:var(--brand-dark);font-weight:700;box-shadow:0 10px 25px rgba(0,0,0,.15)}.homepage__hero-image{width:min(100%,360px);height:auto;margin:auto}.homepage__services{display:grid;grid-template-columns:repeat(3,1fr);gap:1.25rem;padding:5rem 10vw;background:#fff}.homepage__service-card{padding:2rem;border:1px solid #e3e9df;border-radius:1.25rem;background:#fbfcfa}.homepage__contact h2{margin:0 0 .75rem;font-size:clamp(1.8rem,4vw,2.6rem);font-weight:800}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.site-footer{padding:1.5rem 6vw;text-align:center;background:var(--brand-dark);color:#fff}.admin-shell{display:flex;min-height:100vh}.admin-sidebar{width:250px;flex:0 0 250px;padding:28px 20px;color:#fff;background:var(--brand-dark)}.admin-brand{display:flex;align-items:center;gap:12px;margin-bottom:42px;font-size:22px;font-weight:700}.admin-brand img{width:46px;height:46px;object-fit:contain;border-radius:10px;background:#fff}.admin-nav{display:grid;gap:8px}.admin-nav a{padding:12px 14px;border-radius:10px;color:rgba(255,255,255,.82)}.admin-nav a:hover,.admin-nav a.active{color:#fff;background:rgba(255,255,255,.14)}.admin-main{flex:1;min-width:0;padding:34px clamp(22px,4vw,58px);background:var(--surface)}.admin-topbar{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:34px}.admin-heading{min-width:0}.admin-eyebrow{margin:0 0 6px;color:var(--brand);font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.admin-main h1{margin:0;font-size:clamp(28px,4vw,42px);line-height:1.15;color:var(--ink)}.admin-tools{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.admin-date{color:var(--muted);font-size:14px;white-space:nowrap}.admin-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:26px}.stat-card,.admin-panel{border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 8px 24px rgba(55,111,107,.06)}.stat-card{padding:22px}.stat-label{color:var(--muted);font-size:14px}.stat-value{margin:12px 0 8px;font-size:32px;font-weight:700;color:var(--ink)}.stat-change{color:var(--brand);font-size:13px;font-weight:700}.admin-grid{display:grid;grid-template-columns:1.35fr 1fr;gap:20px}.admin-panel{padding:24px}.admin-panel h2{margin:0 0 20px;font-size:19px;color:var(--ink)}.activity{display:grid;gap:16px}.activity-item{display:flex;justify-content:space-between;gap:15px;padding-bottom:16px;border-bottom:1px solid var(--line)}.activity-item:last-child{padding-bottom:0;border-bottom:0}.activity-title{margin:0 0 5px;font-weight:700;color:var(--ink)}.activity-meta{margin:0;color:var(--muted);font-size:13px}.badge{height:fit-content;padding:6px 9px;border-radius:999px;color:var(--brand-dark);background:#e6f2f0;font-size:12px;font-weight:700}.settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.settings-grid .admin-panel{display:grid;gap:18px}.settings-grid label{display:grid;gap:8px;color:var(--muted);font-size:14px;font-weight:700}.settings-grid input,.settings-grid textarea,.settings-grid select{width:100%;border:1px solid var(--line);border-radius:10px;padding:12px;color:var(--ink);background:#fff;font:inherit;font-weight:400}.settings-grid textarea{resize:vertical}.settings-toggle{display:flex!important;align-items:center;justify-content:space-between;padding:14px 0;border-bottom:1px solid var(--line)}.settings-toggle input{width:auto;accent-color:var(--brand-dark)}.settings-save{width:fit-content;border:0;border-radius:10px;padding:12px 18px;color:#fff;background:var(--brand-dark);cursor:pointer;font-weight:700}.settings-alert{margin-bottom:18px;padding:12px 14px;border-radius:10px;color:#27655f;background:#e6f2f0;font-weight:700}.settings-errors{margin-bottom:18px;padding:12px 14px;border-radius:10px;color:#8b3030;background:#fbecec}.brand-preview{max-width:180px;max-height:90px;object-fit:contain;border:1px solid var(--line);border-radius:10px;padding:8px;background:#fff}.preview-box{display:grid;gap:8px;color:var(--muted);font-size:13px;font-weight:700}.preview-box img{display:none}.preview-box.has-preview img{display:block}.settings-section{margin-top:20px}.color-field{display:flex;align-items:center;gap:12px}.color-field input[type=color]{width:52px;height:44px;padding:2px;cursor:pointer}.color-field input[type=text]{flex:1}@media (max-width:900px){.admin-stats{grid-template-columns:repeat(2,1fr)}.admin-grid{grid-template-columns:1fr}}@media (max-width:760px){.site-header,.homepage__hero{flex-direction:column;align-items:flex-start}.homepage__hero{grid-template-columns:1fr;padding:4rem 6vw}.homepage__services{grid-template-columns:1fr;padding:3rem 6vw}.settings-grid{grid-template-columns:1fr}}@media (max-width:640px){.admin-shell{display:block}.admin-sidebar{width:auto;flex-basis:auto;padding:18px}.admin-brand{margin-bottom:18px}.admin-nav{display:flex;flex-wrap:wrap}.admin-nav a{padding:9px 11px;font-size:14px}.admin-main{padding:26px 18px}.admin-topbar{display:block}.admin-tools{margin-top:18px}.admin-stats{grid-template-columns:1fr}}';
    }
}
